-- ============================================================================
-- SC4: Offshore & Marine Logistics joins the catalogue in the Supply Chain &
-- Logistics module. AN APP COURSE: the Suite app is the Marine Logistics
-- Planner (Suite #741), which runs the same engine; the practicals also run
-- in the course's own four calculator panels.
--
-- Catalogue row (module 'supply_chain'; path_order 78; prereq_slug NULL,
-- the lead's decision; school left at its default) plus the three capstones and
-- their eighteen graded fields, generated by tools/course-waves/marine/gen_course.py
-- from the ENGINE'S OWN RUN (marine_capstone.mjs through the vendored
-- engines/supplychain/marineLogistics.js, petrolord-engines e67e7ba), which it
-- refuses to write unless fields.json carries exactly that run's values and the
-- tolerance gradedTolerance.js derives. Deep seeds are three separate
-- migrations; the go-live is a fifth and is HELD until a NextGen production
-- upload carries the route /dashboard/apps/marine.
--
-- WHAT IS GRADED. NKEREFI (Associate) grades a PSV milk run's hours, fuel,
-- fuel cost, deadweight load and binding utilisation and the days of three
-- dedicated voyages; AKOKWA (Professional) grades a week's voyages of demand
-- before rounding, vessel-days, vessels before rounding and spare vessel-days,
-- and a first-fit decreasing deck plan's first-voyage area and second-voyage
-- load utilisation; MGBIDI (Expert) grades a shore base's M/M/c mean wait,
-- probability of waiting and mean time at the base, its M/D/c mean wait and
-- mean queue, and the M/M/c mean wait at the fewest berths meeting a target.
-- Every value is a return value of the engine, identical under every reading
-- the engine states and never a Monte Carlo draw, and the data it was run on
-- is in the case file the prompt names.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('marine', 'Offshore & Marine Logistics', 'supply_chain', 78, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'marine', 'beginner', 'associate',
  'NKEREFI, one PSV serving the Nkerefi cluster (synthetic)',
  'Voyages, capacity and the binding constraint',
  'NKEREFI, one PSV serving the Nkerefi cluster (synthetic). One case file comes with this capstone: nkerefi_case.json carries two calls under the keys voyagePlan:milk-run and voyagePlan:dedicated; paste it into the voyage and fleet calculator''s voyage plan view and choose the block each value needs. The vessel is the PSV Nkerefi Dawn (synthetic): 11.5 knots; a deck of 720 m2 with a usable fraction of 0.8; a deck load of 1650 t; a cargo deadweight of 3100 t; tanks diesel 700 m3, water 900 m3, mud 500 m3; fuel 0.46 t an hour sailing, 0.035 in port and 0.27 at the field. The products diesel (liquid, 0.84 t a m3), water (liquid, 1 t a m3), mud (liquid, 1.35 t a m3). The installations and their field hours: NK-P 5.5 hours, NK-R 7.25 hours, NK-F 4.75 hours; each installation''s cargo for one voyage is in the case file. The milk run sails NK-P, NK-R, NK-F in that order on legs of 47.5, 13.25, 21.5, 58.75 NM; the dedicated voyages go out and back at NK-P 47.5 NM, NK-R 55.25 NM, NK-F 58.75 NM from the base. Both plans state 10.5 port hours a voyage, a weather factor of 1.15 on sailing and field time (and on no other activity) and fuel at 845.5 a tonne. No value depends on any of the readings the engine states (a load exactly at a capacity, the binding tie, the twelve-digit key a count is rounded on, halves to the nearest vessel, a tie of demand and minimum visits, a tie of equal footprints, an exact deck fit, a berth target met exactly, short at equality, the P90 of a requirement) or on a Monte Carlo draw; every choice a value rests on is stated here, and every input a value needs is in the case file: the engine holds no default for any of them. Report six values: the milk run''s total hours; the milk run''s fuel, in tonnes; the milk run''s fuel cost; the milk run''s deadweight load, in tonnes; the utilisation of the milk run''s binding constraint, as a fraction; and the total days of the three dedicated voyages. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','nkerefi_milkrun_hours', 'label','The milk run''s total hours, with the weather factor on the stated activities', 'unit','hours', 'expected',44.724999999999994, 'tol',5e-07),
    jsonb_build_object('key','nkerefi_milkrun_fuel_t', 'label','The milk run''s fuel', 'unit','t', 'expected',12.28725, 'tol',5e-07),
    jsonb_build_object('key','nkerefi_milkrun_fuel_cost', 'label','The milk run''s fuel cost', 'unit','USD', 'expected',10388.869875, 'tol',5e-07),
    jsonb_build_object('key','nkerefi_milkrun_deadweight_t', 'label','The milk run''s deadweight load', 'unit','t', 'expected',2377.5, 'tol',5e-07),
    jsonb_build_object('key','nkerefi_binding_utilisation', 'label','The utilisation of the milk run''s binding constraint', 'unit','fraction', 'expected',0.9522569444444444, 'tol',5e-07),
    jsonb_build_object('key','nkerefi_dedicated_days', 'label','The total days of the three dedicated voyages', 'unit','days', 'expected',3.4968749999999993, 'tol',5e-07)
  )
),
(
  'marine', 'intermediate', 'professional',
  'AKOKWA, a week of supply and one voyage of deck cargo for the Akokwa cluster (synthetic)',
  'Fleet sizing and deck planning',
  'AKOKWA, a week of supply and one voyage of deck cargo for the Akokwa cluster (synthetic). One case file comes with this capstone: akokwa_case.json carries two calls under the keys fleetSize and deckPlan; paste it into the voyage and fleet calculator''s fleet sizing view for the first four values and into the deck calculator for the last two. The vessel is the PSV Akokwa Crest (synthetic): 12.5 knots; a deck of 860 m2 with a usable fraction of 0.72; a deck load of 2150 t; a cargo deadweight of 3850 t; tanks diesel 850 m3, water 1100 m3, brine 450 m3, cement 280 m3; fuel 0.52 t an hour sailing, 0.04 in port and 0.31 at the field. The products diesel (liquid, 0.845 t a m3), water (liquid, 1 t a m3), brine (liquid, 1.25 t a m3), cement (dry, 1.45 t a m3). The installations, their field hours and minimum visits in the week: AK-1 4.5 hours and 2 visits, AK-2 9.25 hours and 3 visits, AK-3 6.75 hours and 2 visits, AK-4 3.5 hours and 1 visit; each installation''s demand for the week is in the case file. The milk run sails AK-1, AK-2, AK-3, AK-4 in that order on legs of 58.5, 16.25, 11.75, 24.5, 83.25 NM, with 14.5 port hours a voyage, a weather factor of 1.25 on sailing and port time (and on no other activity) and fuel at 812.75 a tonne. The period is 7 days with 6.25 days available a vessel; voyageRounding up and vesselRounding up. The deck plan packs the item lines in the case file onto 2 voyages of a deck of 860 m2 at a usable fraction of 0.72 and a deck load of 2150 t (ak-ibc 1.25 m by 1.05 m at 1.35 t, quantity 14, ak-skip 2.6 m by 1.75 m at 2.9 t, quantity 7, ak-c10 2.99 m by 2.44 m at 7.5 t, quantity 11, ak-bskt 8 m by 2.45 m at 7.25 t, quantity 6, ak-tank 5.2 m by 2.35 m at 15.5 t, quantity 5, ak-c20 6.06 m by 2.44 m at 11.5 t, quantity 14, ak-riser 15.25 m by 2.75 m at 41.5 t, quantity 3) by the rule first-fit-decreasing-area. No value depends on any of the readings the engine states (a load exactly at a capacity, the binding tie, the twelve-digit key a count is rounded on, halves to the nearest vessel, a tie of demand and minimum visits, a tie of equal footprints, an exact deck fit, a berth target met exactly, short at equality, the P90 of a requirement) or on a Monte Carlo draw; every choice a value rests on is stated here, and every input a value needs is in the case file: the engine holds no default for any of them. Report six values: the milk run''s voyages of demand before rounding; the vessel-days the week needs; the vessels before rounding; the spare vessel-days; the first voyage''s deck area in the deck plan, in m2; and the second voyage''s deck load utilisation, as a fraction. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','akokwa_voyages_exact', 'label','The milk run''s voyages of demand before rounding', 'unit','voyages', 'expected',3.1395348837209305, 'tol',5e-07),
    jsonb_build_object('key','akokwa_vessel_days', 'label','The vessel-days the week needs', 'unit','vessel-days', 'expected',10.258333333333333, 'tol',5e-07),
    jsonb_build_object('key','akokwa_vessels_exact', 'label','The vessels before rounding', 'unit','vessels', 'expected',1.6413333333333333, 'tol',5e-07),
    jsonb_build_object('key','akokwa_spare_vessel_days', 'label','The spare vessel-days', 'unit','vessel-days', 'expected',2.241666666666667, 'tol',5e-07),
    jsonb_build_object('key','akokwa_ffd_v1_area_m2', 'label','The first voyage''s deck area, first-fit decreasing', 'unit','m2', 'expected',619.0737000000004, 'tol',5e-07),
    jsonb_build_object('key','akokwa_ffd_v2_load_utilisation', 'label','The second voyage''s deck load utilisation, first-fit decreasing', 'unit','fraction', 'expected',0.010139534883720932, 'tol',5e-07)
  )
),
(
  'marine', 'advanced', 'expert',
  'MGBIDI, the Mgbidi supply base and its fleet (synthetic)',
  'Shore base queues, variability and the limits',
  'MGBIDI, the Mgbidi supply base and its fleet (synthetic). One case file comes with this capstone: mgbidi_case.json carries three calls under the keys shoreBase:mmc, shoreBase:mdc and fleetVariability; paste it into the shore base calculator and choose the block each value needs. The base has 3 berths and 4.6 arrivals a day over a 20-hour working day; a call needs 1.5 fixed hours, 84 lifts at 14 an hour and 540 m3 of bulk at 120 m3 an hour, with concurrent true (the lifts and the bulk at the same time). The block shoreBase:mmc states the model M/M/c and a target mean wait of 0.35 hours; the block shoreBase:mdc states the model M/D/c. The block fleetVariability runs the seeded Monte Carlo (seed 20291117, 20000 draws) in the variability calculator: report what it returns with its seed and draws in your plan; none of its figures is graded. No value depends on any of the readings the engine states (a load exactly at a capacity, the binding tie, the twelve-digit key a count is rounded on, halves to the nearest vessel, a tie of demand and minimum visits, a tie of equal footprints, an exact deck fit, a berth target met exactly, short at equality, the P90 of a requirement) or on a Monte Carlo draw; every choice a value rests on is stated here, and every input a value needs is in the case file: the engine holds no default for any of them. Report six values: the M/M/c mean wait, in hours; the M/M/c probability of waiting; the M/M/c mean time at the base, in hours; the M/D/c mean wait, in hours; the M/D/c mean queue; and the M/M/c mean wait at the fewest berths that meet the target, in hours. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','mgbidi_mmc_wait_hours', 'label','The M/M/c mean wait', 'unit','hours', 'expected',1.9018994157247162, 'tol',5e-07),
    jsonb_build_object('key','mgbidi_mmc_probability_wait', 'label','The M/M/c probability of waiting', 'unit','probability', 'expected',0.3233229006732018, 'tol',5e-07),
    jsonb_build_object('key','mgbidi_mmc_time_at_base_hours', 'label','The M/M/c mean time at the base', 'unit','hours', 'expected',9.401899415724717, 'tol',5e-07),
    jsonb_build_object('key','mgbidi_mdc_wait_hours', 'label','The M/D/c mean wait', 'unit','hours', 'expected',1.020033589096101, 'tol',5e-07),
    jsonb_build_object('key','mgbidi_mdc_mean_queue', 'label','The M/D/c mean queue', 'unit','vessels', 'expected',0.2346077254921032, 'tol',5e-07),
    jsonb_build_object('key','mgbidi_target_wait_hours', 'label','The M/M/c mean wait at the fewest berths that meet the target', 'unit','hours', 'expected',0.07902133066152323, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
